// Invented two-colour checkerboard, encoded by macOS ImageIO and stamped with fixture EXIF/XMP/IPTC using ExifTool 13.64.
// The location values and camera identifiers are made up. No participant material was used.
const base64 = {
  jpg: "",
  png: "",
  heic: "",
} as const;
export const photoFixture = (ext: keyof typeof base64) => Uint8Array.from(atob(base64[ext]),ch => ch.charCodeAt(0));
